		// A game function or data the effect code uses; game_addr() gives its address in the running game
		struct Id
		{
			uint32_t index = UINT32_MAX; // none: game_addr() gives 0

			constexpr Id() = default;
			explicit constexpr Id(uint32_t i) : index(i) {}
			constexpr explicit operator bool() const { return index != UINT32_MAX; }
		};

